begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) values('af600000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','f6-owner@example.test',now(),now(),now());
insert into public.organizations(id,name,slug,status) values('bf600000-0000-4000-8000-000000000001','Revisão fictício','f6-synthetic','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values('cf600000-0000-4000-8000-000000000001','bf600000-0000-4000-8000-000000000001','Sede Revisão','sede','headquarters'),('cf600000-0000-4000-8000-000000000002','bf600000-0000-4000-8000-000000000001','Campus Revisão','campus','campus');
insert into public.organization_memberships(organization_id,user_id,role,status,default_unit_id) values('bf600000-0000-4000-8000-000000000001','af600000-0000-4000-8000-000000000001','owner','active','cf600000-0000-4000-8000-000000000001');
select set_config('f6.org','bf600000-0000-4000-8000-000000000001',true);select set_config('f6.unit','cf600000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"af600000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select public.finance_f1(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid],'catalog','{"id":"df600000-0000-4000-8000-000000000001","kind":"account","name":"Banco Revisão"}');
select public.finance_f1(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid],'catalog','{"id":"df600000-0000-4000-8000-000000000002","kind":"category","name":"Doações Revisão","direction":"income"}');
select public.finance_f1(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid],'entry',jsonb_build_object('id','ab600000-0000-4000-8000-000000000001','kind','income','amountCents','1000','description','Previsão inicial fictícia','account','df600000-0000-4000-8000-000000000001','category','df600000-0000-4000-8000-000000000002','competence',current_date,'due',current_date,'method','pix'));
reset role;

set local role authenticated;
select public.finance_f1(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid],'entry',jsonb_build_object('id','ab600000-0000-4000-8000-000000000002','kind','income','amountCents','10000','description','Receita fictícia F6','account','df600000-0000-4000-8000-000000000001','category','df600000-0000-4000-8000-000000000002','party','Pessoa fictícia F6','competence',current_date,'due',current_date,'paid',current_date,'method','pix'));
select set_config('f6.filters',jsonb_build_object('from',current_date,'to',current_date,'dateBy','cash','report','book')::text,true);
select lives_ok($$select public.finance_f6(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid],'report',current_setting('f6.filters')::jsonb)$$,'consulta F6 executa com identidade confirmada');
select set_config('f6.result',public.finance_f6(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid],'report',current_setting('f6.filters')::jsonb)::text,true);
select is(jsonb_array_length(current_setting('f6.result')::jsonb->'rows'),2,'previsão e realizado separados');
select is((select sum((x->>'amount')::bigint)::text from jsonb_array_elements(current_setting('f6.result')::jsonb->'rows')x where x->>'basis'='actual'),'10000','caixa realizado exato');
select is((select sum((x->>'amount')::bigint)::text from jsonb_array_elements(current_setting('f6.result')::jsonb->'rows')x where x->>'basis'='forecast'),'1000','principal previsto não soma ao realizado');
select is(jsonb_array_length(current_setting('f6.result')::jsonb->'accounting'),2,'exportação inclui duas partidas');
select is((select sum((x->>'delta')::bigint)::text from jsonb_array_elements(current_setting('f6.result')::jsonb->'accounting')x),'0','lote contábil fecha em zero');
select is(current_setting('f6.result')::jsonb->'balances'->0->>'closing','10000','saldo até data final');
select throws_ok($$select public.finance_f6(current_setting('f6.org')::uuid,array['cf600000-0000-4000-8000-000000000099'::uuid],'report',current_setting('f6.filters')::jsonb)$$,'42501',null,'unidade fora de escopo é recusada integralmente');
select throws_ok($$select public.finance_f6(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid,current_setting('f6.unit')::uuid],'report',current_setting('f6.filters')::jsonb)$$,'22023',null,'unidades repetidas recusadas');
select is(jsonb_array_length(public.finance_f6(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid],'report',current_setting('f6.filters')::jsonb||'{"min":"20000"}')->'rows'),0,'filtro de valor antes do relatório');
select throws_ok($$select public.finance_f6(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid],'report',current_setting('f6.filters')::jsonb||'{"report":"budget","provider":"asaas"}')$$,'22023',null,'orçamento recusa dimensão incompatível');
select throws_ok($$select public.finance_f6(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid],'report',current_setting('f6.filters')::jsonb||'{"report":"divergences","category":"df600000-0000-4000-8000-000000000002"}')$$,'22023',null,'extrato não presume categoria');
select lives_ok($$select public.finance_f6(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid],'budget',jsonb_build_object('id','ab600000-0000-4000-8000-000000000010','month',date_trunc('month',current_date)::date,'category','df600000-0000-4000-8000-000000000002','amountCents','15000','version',0,'reason','Orçamento fictício de homologação'))$$,'administrador define orçamento auditado');
select throws_ok($$select public.finance_f6(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid],'budget',jsonb_build_object('id','ab600000-0000-4000-8000-000000000010','month',date_trunc('month',current_date)::date,'category','df600000-0000-4000-8000-000000000002','amountCents','20000','version',0,'reason','Repetição fictícia obsoleta'))$$,'40001',null,'versão obsoleta não reescreve orçamento');
select is(public.finance_f6(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid],'report',current_setting('f6.filters')::jsonb)->'budgets'->0->>'amount','15000','orçamento preservado');
select public.finance_f1(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid],'void',jsonb_build_object('id','ab600000-0000-4000-8000-000000000002','version',1,'reason','Estorno fictício F6','date',current_date,'requestId','ab600000-0000-4000-8000-000000000011'));
select is((select sum((x->>'amount')::bigint)::text from jsonb_array_elements(public.finance_f6(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid],'report',current_setting('f6.filters')::jsonb)->'rows')x where x->>'basis'='actual'),'0','estorno zera caixa sem apagar original');
reset role;
select is((select count(*)::integer from public.audit_logs where organization_id=current_setting('f6.org')::uuid and action='finance.budget_saved'),1,'orçamento deixa auditoria');
select ok(not has_function_privilege('anon','public.finance_f6(uuid,uuid[],text,jsonb)','execute'),'visitante sem execução F6');
select ok(not has_table_privilege('authenticated','private.finance_budgets','select'),'orçamentos não expostos diretamente');
set local role authenticated;
select public.finance_f1(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid],'catalog','{"id":"df600000-0000-4000-8000-000000000003","kind":"account","name":"Caixa F6"}');
select public.finance_f1(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid],'catalog','{"id":"df600000-0000-4000-8000-000000000004","kind":"category","name":"Taxas F6","direction":"expense"}');
select public.finance_f1(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid],'entry',jsonb_build_object('id','ab600000-0000-4000-8000-000000000020','kind','opening','amountCents','10000','description','Abertura fictícia F6','account','df600000-0000-4000-8000-000000000001','competence',current_date,'due',current_date,'paid',current_date,'method','cash'));
select public.finance_f1(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid],'entry',jsonb_build_object('id','ab600000-0000-4000-8000-000000000021','kind','transfer','amountCents','1000','description','Transferência fictícia F6','account','df600000-0000-4000-8000-000000000001','destination','df600000-0000-4000-8000-000000000003','competence',current_date,'due',current_date,'paid',current_date,'method','bank'));
select set_config('f6.result',public.finance_f6(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid],'report',current_setting('f6.filters')::jsonb)::text,true);
select is((select count(*)::integer from jsonb_array_elements(current_setting('f6.result')::jsonb->'rows')x where x->>'kind'='opening'),1,'saldo inicial não é receita');
select is((select count(*)::integer from jsonb_array_elements(current_setting('f6.result')::jsonb->'rows')x where x->>'kind'='transfer'),2,'transferência aparece nas duas contas');
select is((select sum((x->>'amount')::bigint)::text from jsonb_array_elements(current_setting('f6.result')::jsonb->'rows')x where x->>'kind'='transfer'),'0','transferência consolidada não infla caixa');
select is((select sum((x->>'closing')::bigint)::text from jsonb_array_elements(current_setting('f6.result')::jsonb->'balances')x),'10000','saldo inicial preservado na posição das contas');
select public.finance_f2(current_setting('f6.org')::uuid,current_setting('f6.unit')::uuid,'settle',jsonb_build_object('id','ab600000-0000-4000-8000-000000000022','title','ab600000-0000-4000-8000-000000000001','version',1,'principal','400','interest','0','fine','0','discount','0','fee','20','feeCategory','df600000-0000-4000-8000-000000000004','account','df600000-0000-4000-8000-000000000001','date',current_date,'method','pix','reason','Baixa parcial fictícia F6'));
select set_config('f6.result',public.finance_f6(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid],'report',current_setting('f6.filters')::jsonb)::text,true);
select is((select sum((x->>'amount')::bigint)::text from jsonb_array_elements(current_setting('f6.result')::jsonb->'rows')x where x->>'basis'='forecast'),'600','baixa parcial reduz apenas principal em aberto');
select is((select sum((x->>'amount')::bigint)::text from jsonb_array_elements(current_setting('f6.result')::jsonb->'rows')x where x->>'basis'='actual' and x->>'kind' in('income','expense')),'380','caixa líquido registra recebimento menos taxa uma vez');
reset role;
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) values('af600000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','f6-finance@example.test',now(),now(),now());
insert into public.organization_memberships(id,organization_id,user_id,role,status,default_unit_id) values('af690000-0000-4000-8000-000000000001',current_setting('f6.org')::uuid,'af600000-0000-4000-8000-000000000002','finance','active',current_setting('f6.unit')::uuid);
insert into public.membership_unit_access(membership_id,unit_id,access_level) values('af690000-0000-4000-8000-000000000001',current_setting('f6.unit')::uuid,'admin');
select set_config('request.jwt.claims','{"sub":"af600000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$select public.finance_f6(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid],'report',current_setting('f6.filters')::jsonb)$$,'tesouraria consulta unidade concedida');
select throws_ok($$select public.finance_f6(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid,'cf600000-0000-4000-8000-000000000002'::uuid],'report',current_setting('f6.filters')::jsonb)$$,'42501',null,'consolidação não admite unidade não concedida');
select throws_ok($$select public.finance_f6(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid],'report',current_setting('f6.filters')::jsonb||'{"report":"members"}')$$,'42501',null,'contribuições individuais não expostas à tesouraria comum');
select is((select count(*)::integer from jsonb_array_elements(public.finance_f6(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid],'report',current_setting('f6.filters')::jsonb)->'rows')x where x->>'party' is not null),0,'nomes individuais não vazam em relatórios comuns');
reset role;
select set_config('request.jwt.claims','{"sub":"af600000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
update public.organization_memberships set status='suspended' where id='af690000-0000-4000-8000-000000000001';
reset role;
select set_config('request.jwt.claims','{"sub":"af600000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select public.finance_f6(current_setting('f6.org')::uuid,array[current_setting('f6.unit')::uuid],'report',current_setting('f6.filters')::jsonb)$$,'42501',null,'suspensão atual recusa relatório');
reset role;
select * from finish();
rollback;
